package apicontract

import (
	"github.com/oberthci/oberth/internal/stepmodel"
)

// RunsTools declares the runs service operations.
type RunsTools struct {
	Logs           Binding[LogsArgs, LogResult]              `tool:"logs" command:"log" flow:"true" summary:"Read retained logs for a native object." tail:"200" desc:"Read retained native log bytes for a selected object. Discover node and container selectors before narrowing a log window."`
	RunCancel      Binding[RunCancelArgs, Receipt]           `tool:"run_cancel" summary:"Cancel a run." desc:"Request cancellation of an authorized run with an audit reason. Use run_get to observe its final durable state." mutation:"true" check:"run_get"`
	RunCheck       Binding[RunCheckArgs, RunCheckResult]     `tool:"run_check" command:"check" flow:"true" summary:"Check pipeline files before pushing." desc:"Inspect authored pipeline files without accepting work or changing state. Correct the findings before pushing the pipeline."`
	RunGet         Binding[RunGetArgs, RunRecord]            `tool:"run_get" summary:"Read a run and its admitted logical steps in plan order." desc:"Read a run and its admitted logical steps in plan order. Continue with next_step_offset or use run_logs for native evidence." get:"/api/runs/{run}"`
	RunHoldAbandon Binding[RunHoldAbandonArgs, Receipt]      `tool:"run_hold_abandon" command:"run hold release" summary:"Release a held failed step." desc:"Release a held failed container without rerunning its command. Use run_get to observe the native result. The TTL bounds cooperative waiting, not cleanup or run finalization." mutation:"true" check:"run_get"`
	RunHoldExec    Binding[RunHoldExecArgs, ExecResult]      `tool:"run_hold_exec" summary:"Inspect a held step with a command." seconds:"900" desc:"Run any command with the held step identity and mounts. It can change files, including outputs Argo collects for downstream steps. Only declared and resolved secret input routes are excluded; image contents, fetched values and readable shared state cannot be certified secret-free. Commands receive no stdin; detached process groups are outside cleanup. Running a command here means this run can no longer count as green CI, promotion or publication evidence. An armed step that does not succeed also excludes the run, even without inspection; armed steps that all succeed remain ordinary unless inspected. Its audit mark precedes dispatch and remains if dispatch fails. The audit records kind, step, reason, argument count and SHA-256 of the argument list, never the command arguments." mutation:"true" check:"run_get"`
	RunHoldList    Binding[RunHoldListArgs, HoldPage]        `tool:"run_hold_list" summary:"List current held steps and their availability." desc:"List current holds and their live availability. Inspect with run_hold_exec, push a fix, then release with run_hold_abandon."`
	RunList        Binding[RunListArgs, RunPage]             `tool:"run_list" summary:"List authorized runs and complete logical-step counts." desc:"List authorized runs and complete logical-step counts. Continue older history with the returned record-ID cursor." get:"/api/runs"`
	RunLogs        Binding[RunLogsArgs, LogResult]           `tool:"run_logs" command:"log" flow:"true" summary:"Read retained log bytes or discover native containers." desc:"Read retained log bytes or discover native containers. Keep the same filter and use next_byte_offset when more bytes remain." get:"/api/runs/{run}/logs" tail:"200"`
	RunPurge       Binding[RunPurgeArgs, Receipt]            `tool:"run_purge" summary:"Purge retained run logs." desc:"Purge retained run log bytes after confirming the target and audit reason. Use run_logs to inspect the resulting retention state." access:"unscoped_admin" mutation:"true" admin:"run-purge" bytes:"131072" check:"run_get"`
	RunResume      Binding[RunResumeArgs, ResumeResult]      `tool:"run_resume" summary:"Resume a failed run on a pushed fix." desc:"Resume the failed part through native retry while keeping passed work. This run is assisted and never evidence. After it passes, obtain consent and call run_rerun once for an unassisted run." mutation:"true" check:"run_get"`
	RunRerun       Binding[RunRerunArgs, Receipt]            `tool:"run_rerun" summary:"Submit another run of an authorized recorded source." desc:"Submit another run of an authorized recorded source. Keep the returned ID and use run_wait to observe it." mutation:"true" check:"run_get"`
	RunWait        Binding[RunWaitArgs, WaitResult]          `tool:"run_wait" summary:"Wait for a run to finish, hold or change." desc:"Wait for a run to finish, enter a hold or change. Use the returned state to choose logs, hold assistance or the next event wait." wait:"true"`
	Status         Binding[StatusArgs, stepmodel.RunSummary] `tool:"status" command:"commit status" summary:"Show a commit's visible run state." desc:"Read the visible run state for a commit or reference. Use run_get for logical steps and run_logs for evidence."`
	Wait           Binding[WaitArgs, WaitResult]             `tool:"wait" command:"commit wait" summary:"Wait for a commit or reference to change." desc:"Wait for the selected object or run to finish without submitting work. Continue with run_get or events_wait after a timeout." wait:"true"`
}
